import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷四","description":"西溪易說 - 西溪易說卷四","frontmatter":{"title":"西溪易說卷四","description":"西溪易說 - 西溪易說卷四"},"headers":[],"relativePath":"classics/xixi/005.md","filePath":"classics/xixi/005.md"}'),i={name:"classics/xixi/005.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷四" tabindex="-1">西溪易說卷四 <a class="header-anchor" href="#西溪易說卷四" aria-label="Permalink to “西溪易說卷四”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷎ 艮下坤上</p><p>謙：</p><p>謙：亨。君子有終。彖曰：「謙，亨」。天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可逾，君子之終也。</p><p>坤上艮下，山本高也，今在地下，地高於山，謙而下人之義也。湘卿雲：「矯亢為行，其運必窒；中遜為行，無敵不通。」謙所以「亨」也。九三以「勞謙」為謙卦之主，故君子有終。謙道至難，小人非不能勉強於日月，然不能持久，惟居子乃能終身行之。天居上，惟其下濟萬物，故生生之道顯然可見，是天道以謙而光明也。地惟順下，故其氣上騰而能交於天，是地道以謙而上行也。謙而亨，天地之理也。日盈則昃，月盈則蝕，天道盈虧而益謙也。水流而不盈，盈科而必行，地道變盈而流謙也。高明之家，鬼闞其室，虛室生白，吉祥必至，鬼神害盈而福謙也。自後者，人先之；自下者人高之，人道惡盈而好謙也。尊者謙則愈光，卑者謙則不可逾，所以君子終始乎謙也。</p><p>象曰：地中有山，謙；君子以裒多益寡，稱物平施。</p><p>山合在地上，今四圍地高，而山在其中，猶人降尊而就卑之象也，故為「謙」。君子觀此，則「裒多益寡，稱物平施」。論天下之勢，有上下、尊卑、貴賤、多寡，至懸絕也。至於謙，則上有以待下，尊有以降卑，貴有以下賤，多有以益寡，而無適不平矣。故「裒多益寡，稱物平施」，謙之事也。</p><p>初六，謙謙君子，用涉大川，吉。象曰：「謙謙君子」，卑以白牧也。以六居下，謙之至也，故曰「謙謙君子」。以謙為德，眾所共與，用以濟難，何往不吉？二、三四互體為坎，「坎」居其前，「大川」之象。象曰：「卑以自牧也。」牧，養也。言君子處卑，其自養之道當如此。</p><p>六二，鳴謙，貞吉。象曰：「鳴謙貞吉」，中心得也。</p><p>初以謙自牧，守己而謙也。二「鳴謙」，謙形於言也。言者，心之聲也。卑辭遜語以為謙，則易流於諂，必出於中心之正則吉，故曰「鳴謙貞吉」。象曰：「中心得也」，非徒飾辭於外以為謙也。二居互體，為「坎」之下，「坎」為有言，謙之見於言也。九三，勞謙，君子有終，吉。象曰：「勞謙君子」，萬民服也。卦惟一陽居艮體之上，處坤體之下，地中之山，三爻當之。「勞謙」，有功而謙也。此爻居互體之中，萬物勞乎坎，故能「勞謙」。君子有終。此爻居艮之上，萬物終乎艮，故能有終。正如周公有大勳勞於天下，居三公之位，而躬吐握之禮以下士也。卦辭「君子有終吉」，惟此爻盡之。繫辭曰：「勞而不伐，冇功而不德，厚之至也。」語以其功下人者也。德言盛，禮言恭，謙也者，致恭以存其位者也。象曰：萬民服也，天下惟謙乃可以服人之心，倘或矜伐，則爭之者至矣。</p><p>六四，無不利，撝謙。象曰：「無不利撝謙」，不違則也。</p><p>四居上，體坤下。坤，天下之至順也。四位柔，以柔居之，順之至也。謙而至此，指撝動作，但見其無不順爾，故曰「無不利，撝謙」。堯之允恭克讓，舜之溫恭允塞，夫子之恭而安是也。象曰「不違則」，至此從容中道，動容周旋皆中禮，與道為一，安得違？曰「不違」，則見謙之成熟處。</p><p>六五，不富以其鄰，利用侵伐，無不利。象曰：「利用侵伐」，徵不服也。</p><p>五，君位，以柔處之，處君位而能謙也。君有天下之富者也。不有其富而以與其鄰，以大事小，樂天者也。正如湯事葛，文王事昆夷，是以天道為心而與物無競，謙道之至者也。以此事人而猶不服，則徵葛事昆夷，非湯、文之咎也，故曰「利用侵伐，無不利」。象曰：徵不服也。如六五之「謙」而猶不服，然後可用侵伐也。</p><p>上六：鳴謙，利用行師，徵邑國。象曰：「鳴謙」，志未得也。「可用行師」，「徵邑國」也。</p><p>六五「侵伐」，在六五侵伐固無慊，然自以為無慊而侵伐，便害謙體，以侵伐非謙者之事也。故上六又聲言謙之道以贊之曰：「以謙道行，固無不利矣。」然不若退而自「徵邑國」，謂且宜自治，未可便歸咎他人也。正如舜徵有苖，舜之己德，固無慊然矣。方命禹以徂徵，而益猶贊於禹曰：「滿招損，謙受益，時乃天道。」蓋才以己為無慊，而以人有罪可伐，便是自滿，便害謙體，便非天道。禹聞益言而遂班師，便為敷文德，卒之幹羽舞而有苖格，征伐果不用也。故五爻則湯、文用之，上爻則舜、禹用之。象曰：「志未得也。」以上六之志不滿於征伐，故又言曰：「可用行師，徵邑國也。」謂征伐固可以用，不如自治也。必有此二爻，然後見謙道之志。䷏ 坤下震上</p><p>「豫」，「豫」：利建侯行師。彖曰：「豫」，剛應而志行，順以動，「豫」。「豫」順以動，故天地如之，而況「建侯行師」乎？天地以順動，故日月不過，而四時不忒。聖人以順動，則刑罰清而民服。「豫」之時義大矣哉！</p><p>一陽在下體為「謙」，一陽在上體為「豫」。下體「艮」，「艮」，止也，故為「謙」。上體「震」，「震」，動也，動則「豫」。「豫」，逸也。卦一陽居四，居大臣之位，上下所由以取逸也。人情莫不欲安也，莫不欲逸也。然宴安不可懷，懷安必敗名，「豫」固難處也。曰「利建侯行師」，「建侯」，王者不自亨其逸，與天下共有土也。「行師」，惟聖人然後能內外無患，安而不忘危也。六爻無非此意，故彖以一卦之德言之。剛居四而上下應，求者得所願，與者無所疑，志行也。下體順，上體動，以順而動，天地不能違，而況建侯行師？內不自逸，外不忘危，其得順動之體乎？故古之明王立后王君公曰：「不惟逸豫，惟以亂民。」夏諺曰：「吾王不豫，吾何以助？一遊一豫，為諸侯度。」「豫」之「建侯」，意蓋如此。曰：「詰爾戎兵」，周公以告成王，曰：「張皇六師，召公以命元子。」二公當週室盛治之時，乃汲汲以兵為言，「豫」之「行師」，意蓋如此。天地惟以順動而不自已也，故日月不過而四時不忒。聖人惟以順動而不自逸也，故刑罰清而民服。蓋樂民之樂者，民亦樂其樂也，刑罰安用哉？以此觀之，「豫」之時義大矣。</p><p>象曰：雷出地奮，「豫」。先王以作樂崇德，殷薦之上帝，以配祖考。「雷」，天地之樂也。雷出地奮，草木甲拆，而百蟲啟蟄，以豫之象也。王者功成作樂，天下安逸，樂所宜作也。歌頌功德，以薦上帝而配祖考，聖人不敢自有其功，謂凡所以致此者，皆天命之佑，祖宗積德累仁之功，非己之所能為也。此不有其豫之意也。夫惟如此，然後可以長守其豫。</p><p>初六：鳴豫，兇。象曰：「初六鳴豫」，志窮兇也。</p><p>當豫之世，上下皆求「豫」於四，四雖己應而已在下，為先者所得，故不得其平而鳴，非能安者也。故象曰：「志窮兇也。」</p><p>六二：介於石，不終日，貞吉。象曰：「不終日，貞吉」，以中正也。二與五有君臣之分，而九四居大臣之位，為豫卦之主，故「豫」必求四。夫望風掃門以求富貴，君子不屑然也。二純坤體，「坤」，順也，居互體「艮」之下。「艮」，止也；四居互體「坎」之中。「坎」，險也。二能順而止，不肯行險以求四，明知逸樂之不可為也，故介然自守，如石之不可轉，曾不俟終日而止，見幾之敏也。象曰：「以中正也」，以二處中也。繫辭曰：知幾其神乎！君子上交不謟，下交不瀆，其知幾乎！幾者，動之微，吉之先見者也。君子見幾而作，不俟終日。易曰：「介於石，不終日，貞吉。」</p><p>六三：盱豫，悔，遲有悔。象曰：「盱豫」有「悔」，位不當也。</p><p>三不迎上而迎四，趑趄囁嚅以求豫者也。夫以謟事人，雖得富貴，其終必敗，故「悔」。所以悔者，見幾不敏也，故又曰「遲有悔」。盱，徐也。趑趄，囁嚅之貌。九四：由豫，大有得。勿疑，朋盍簪。象曰：「由豫，大有得」，志大行也。</p><p>天下之求豫者皆由四，由四而得豫，故曰「由豫，大有得」。四以君之祿為天下之求士，來者與之而無疑，則士至矣。朋，類也。士以類至，皆峨峨然纓其冠矣，故曰「勿疑，朋盍簪」。正如周公居大臣之位，以禮下士，凡執䞇還䞇而見者，周公無敢驕吝也。象曰：「志大行也。」言上下之志得也。六五：貞疾，恆不死。象曰：「六五貞疾」，乘剛也。「恆不死」，中未亡也。</p><p>以柔居尊位，處豐享豫大之世，易耽於逸樂者也。然九四大臣，六五之畏相也。貞，正也。以九居四五，病其制己，以貞為疾也。所賴者有九四之大臣，故六五之君，其中心之有常者，猶得以不死。蓋人之有欲，天理未嘗泯也。能有所畏而為善，以天理之常者不泯耳。正如伊尹、周公成就太甲、成王為令主，誠非能於太甲、成王天性上有所增益也，即是還得太甲、成王本然之性在天理之外，不容加毫末也。象曰：乘剛也。為九四之剛所制也。中未亡者，以天理在中，未嘗忘也。</p><p>上六：冥豫成，有渝，無咎。象曰：「冥豫」在上，何可長也？上六以陰柔之資，處豫之極，顛冥乎逸豫而不知返也，故曰「冥豫」。然惡既成矣，渝，變也。苟能變而從善，亦可無咎。蓋為善為惡之機，相去不隔蠅翼。書曰：「吉人為善，惟日不足。兇人為不善，亦惟日不足。」其不足之心則一也。轉惡從善，特一轉樞之力爾。雖然，以六處上，無行健之德，非能自克也，故象曰「何可長也」。䷹ 震下兌上</p><p>隨</p><p>隨：元亨，利貞，無咎。彖曰：隨，剛來而下柔，動而說，隨。大亨貞，無咎，而天下隨時。隨時之義大矣哉！</p><p>兌上震下上體說，下體動，動而悅，隨人之義也。「元亨利貞無咎」，謂九五也。以九居五，為隨之主，備大亨正之體，而上下五爻皆隨之，故曰「夭亨貞，而天下隨時」。天下皆隨，隨之義大矣。然不能遽隨也，必當其時之可，彖辭所以貴於「隨時」也。在六爻，五為隨主，上下皆當隨五，然不容遽至五也。初必隨二，故「出門」交二；二必隨三，故系三「小子」；三必隨四，故「系四丈夫」，皆有次第終之。九四合下三爻以上隨五，故五「孚於嘉」。以其不能遽隨，故彖發「隨時」之義。上六失隨而不隨者也，故取拘繫。</p><p>象曰：澤中有雷，隨。君子以嚮晦入宴息。「澤中有雷」，息雷也。雷雲興則為雨，既雨而止，則雷息於澤。既息而動，則澤氣又隨之而升。既升乎天，則又決而為雨。君子於此得「隨時」之義。蓋天下屈伸一理也，動息一機也。此時之屈，乃所以為異日之伸；今日之息，乃所以為後日之動也。故君子當「嚮晦」之時，且須「入宴息」。</p><p>初九，官有渝，貞吉。出門交有功。象曰：「官有渝」，從正吉也；「出門交有功」，不失也。古者官有定守，祝不治庖而工不易技。當隨之時，天下從君。初居震，欲動以隨，將離其官守而往也。從君，理之正也，故「吉」。然二、三、四在前時，未得隨也。出門交二，隨二而進，則「有功」矣。象曰「從正吉也」，謂從君正也。曰「不失」者，交二而終得，五不失其所隨也。</p><p>六二，系小子，失丈夫。象曰：「系小子」，弗兼與也。</p><p>隨之六爻，以漸而隨，不能越次，故初隨二，二隨三，三隨四，四合而隨五。二雖五之應，然未能隨五也，且隨三，小子，三也；丈夫，初也。隨三不隨初，上進也。象曰：「弗兼與也」，當舍初隨三也。</p><p>六三，系丈夫，失小子。隨有求得，利居貞。象曰：「系丈夫」，志舍下也。</p><p>上隨九四，「系丈夫」也；下舍六二，「失小子」也。求四必得四，故曰「隨有求得」。當以正隨，故曰「利居貞」。以三位不中，易於詭隨，故有此戒。象曰「志舍下也」，言舍二也。</p><p>九四，隨有獲，貞兇。有孚在道，以明，何咎！象曰：「隨有獲」，其義兇也。「有孚在道」，明功也。</p><p>下三爻上隨而四得之，故曰「隨有獲」。然九五在上，為隨之主，豈容天下隨四？以正言之，「兇」也。然四志在隨五，非利人之己隨也。五，孚於嘉。有孚在道之君也，能明己志，故「無咎」也。象曰：「明功也。」率天下以隨五，皆四之功也，五終能明之。</p><p>九五，孚於嘉，吉。象曰：「孚於嘉吉」，位正中也。</p><p>九五居君位，得大亨正之體，為隨之主，天下之善皆歸之矣。為九五者，必有以誠服其心，則吉矣，故曰「孚於嘉，吉」。象曰：「位正中也。」以九五居正中之位，而天下得所願矣。</p><p>上六，拘繫之，乃從維之，王用亨於西山。象曰：「拘繫之」，上窮也。</p><p>眾爻皆隨五，而六在外，失時而不隨者。一夫不隨，非隨之善，故必拘繫又從維之，不容其不隨也。王，九五也，得上六，則隨道亨矣。六居兌上，西山之象也。象曰：上窮也。窮而後隨，故取拘繫。如藝祖皇帝遣將平諸僭偽，必戒之曰：「會取會取。他本無罪，即是自家著他不得。」蓋此意也。䷑ 巽下艮上</p><p>蠱，</p><p>蠱：元亨，利涉大川。先甲三日，後甲三日。彖曰：蠱，剛上而柔下，巽而止，蠱。「蠱，元亨」，而天下治也。「利涉大川」，往有事也。「先甲三日，後甲三日」，終則有始，天行也。</p><p>蠱，壞也。於文，皿蟲為蠱，器蛀為蠱。艮上巽下風落山，物之蠱也。卦自泰來，自古壞亂之原，多起於太平之世。天下不常治，治亂相因，成毀相仍，理之常也。既蠱矣，安得元亨？蓋天下之理，不亂則不治，不毀則不新。君得幹蠱之臣，父得幹蠱之子，則蠱可亨矣。然必曰「元亨」者，就元處亨，乃幹蠱之道也。今器皿蠱壞，有杯樸在，取元存杯樸而修飾之，則器復新矣。天下雖大弊極亂，要之祖宗法度紀綱尚在，但廢壞不修爾。取猶存之法度紀綱，一振而起之，則天下復治矣。故就元取亨，乃治蠱之道也。「利涉大川」，不以既蠱而止，其濟艱難可也。「先甲三日，後甲三日」，天地之道，終而復始。出甲於甲，奮軋於乙，明炳於丙，大盛於丁，藏茂於戊，埋死於己，斂庚於庚，息辛於辛，懷任於壬，陳揆於癸。既陳揆於癸，依然出甲於甲。今曰「先甲三日」，蓋先甲三日而得辛。曰「後甲三日」，蓋後甲三日而得丁。治蠱之道，不過就息辛中取得種子，來陳揆而敷菑之，依前出甲奮軋，而大盛於丁矣。此即「蠱元亨」之意也。彖曰：蠱，剛上柔下。卦自泰來，初剛居上，上柔反下，物之傾撓，皆以下柔，故剛上柔下為蠱義。巽，順也。艮，止也。順而止之，治蠱之道也。臣幹君，子幹父，全用不得剛，全卦皆以順正為義。蠱而亨之，天下復治。曰「往有事」，求以濟蠱也。書曰：「予惟往求朕攸濟。」曰「往」曰「求」，乃有事之意。聖人以義斷命，不委於命，一以人合天，不委於天，故曰「往有事」。終則有始，天行也，未有終而不始者，無終蠱之理也，天道自如此。象曰：山下有風，蠱。君子以振民育德。</p><p>風落山，蠱之象也。風落山，則草木皆落實，然生意已存於所落之實。君子體此，則振民育德。蓋大弊極壞之世，不過窮民流徙，而賢者失職，振而育之，使流徙之窮民得所歸，失職之賢者有所養，則天下復治矣。夫子曰：「謹權量，審法度，修廢官，舉逸民，天下歸心焉。」夫子處春秋之世，不過如此。廢官逸民，乃治蠱之種子也。初六，幹父之蠱，有子，考無咎，厲，終吉。象曰：「幹父之蠱」，意承考也。</p><p>全卦之義，在順而止。為臣子者，得幹蠱之名，而使君父受致蠱之咎，非臣子之意也。故必置君父於無過，然後為治蠱之善，此順止之義也。初六當蠱之始，事方弊壞，而治之易為力。曰「幹父之蠱，有子，考無咎」，謂有幹蠱之子，當先意承志，使人不知其為考之咎也。「厲終吉」，始雖危，然終吉也。象曰：「意承考也」，謂以善繼志也。如夫子稱孟莊子之孝，然後盡幹蠱之道。</p><p>九二，幹母之蠱，不可貞。象曰：「幹母之蠱」，得中道也。二居內卦之中，母之蠱也。幹母之蠱，尤當遜順，不可貞固，所謂「見志不從，又敬不違」也。象曰：「得中道也」，不至太過也。</p><p>九三，幹父之蠱，小有悔，無大咎。象曰：「幹父之蠱」，終無咎也。</p><p>三位剛，又以九居之，以剛居剛，過乎剛也。過乎剛，非幹蠱之善，故「小有悔」。然意在幹蠱，故無大咎，正如章子之責善。</p><p>六四，裕父之蠱，往見吝。象曰：「裕父之蠱」，往未得也。四位柔，以柔居柔，過乎柔也。又不足以幹蠱，反能增益父之蠱而已，故曰「裕父之蠱」，往必有見吝，故象曰「往未得也」。</p><p>六五，幹父之蠱，用譽。象曰：「幹父用譽」，承以德也。</p><p>五，君父之位，所致蠱者皆五為之也。今以六居之，柔而得中，故盡幹蠱之善。曰「用譽」者，不惟使其「考無咎」，又能揚名以顯其父母也。象曰「承以德也」，以德承父，宜其名之彰也，至此然後盡幹蠱之道也。如有禹，則鯀得與於郊；有安世、延年，則張湯、杜周得免於酷吏，乃所謂以德承考者也。</p><p>上九：不事王侯，高尚其事。象曰：「不事王侯」，志可則也。九居上，「不事王侯」，不與幹蠱者也。當天下弊壞之時，君子所當用力，豈容上九之「高尚」？蓋下五爻皆有事，則幹蠱有人矣，故己可以長往。有皋、夔、稷、契，則巢、許可以去；有太公、閎、散，則夷、齊可以去；有蕭、張、信、越，則黃、綺諸公可以去；有寇、鄧、賈、景，則嚴陵可以去。雖然，非苟去也，清風義概，使人遐想，千載而下，所賴以激貪而起懦者，則是或一道也，故曰「志可則也」。西溪易說卷四，</p>',56)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
